Problem:
A supermarket can purchase two types of refrigerators to properly store their food, refrigerator ABC and refrigerator XYZ, and they have different specifications to consider. Refrigerator ABC is larger and can store 120 items but uses 3 kWh. Refrigerator XYZ is smaller more efficient and can store 80 items but uses 1 kWh. Due to soaring electric prices, the store is limited to at most 55 kWh but must store at least 1500 items. The store must have at least 8 refrigerator ABC’s and 5 refrigerator XYZ’s. How many of each type of refrigerator should the supermarket purchase to minimize the number of refrigerators needed?

Model and facts:
{
 "model": {
  "variables": [
   {
    "name": "ABC refrigerators purchased",
    "lower": 0.0,
    "upper": null,
    "integer": true
   },
   {
    "name": "XYZ refrigerators purchased",
    "lower": 0.0,
    "upper": null,
    "integer": true
   }
  ],
  "objective": {
   "sense": "min",
   "terms": [
    {
     "var": "ABC refrigerators purchased",
     "coef": 1.0
    },
    {
     "var": "XYZ refrigerators purchased",
     "coef": 1.0
    }
   ]
  },
  "constraints": [
   {
    "name": "energy_limit",
    "terms": [
     {
      "var": "ABC refrigerators purchased",
      "coef": 3.0
     },
     {
      "var": "XYZ refrigerators purchased",
      "coef": 1.0
     }
    ],
    "sense": "<=",
    "rhs": 55.0
   },
   {
    "name": "item_storage",
    "terms": [
     {
      "var": "ABC refrigerators purchased",
      "coef": 120.0
     },
     {
      "var": "XYZ refrigerators purchased",
      "coef": 80.0
     }
    ],
    "sense": ">=",
    "rhs": 1500.0
   },
   {
    "name": "min_ABC",
    "terms": [
     {
      "var": "ABC refrigerators purchased",
      "coef": 1.0
     }
    ],
    "sense": ">=",
    "rhs": 8.0
   },
   {
    "name": "min_XYZ",
    "terms": [
     {
      "var": "XYZ refrigerators purchased",
      "coef": 1.0
     }
    ],
    "sense": ">=",
    "rhs": 5.0
   }
  ]
 },
 "facts": {
  "objective": 15.0,
  "values": {
   "ABC refrigerators purchased": 10.0,
   "XYZ refrigerators purchased": 5.0
  },
  "binding": [
   "min_XYZ"
  ],
  "slack": {
   "energy_limit": 20.0,
   "item_storage": 100.0,
   "min_ABC": 2.0,
   "min_XYZ": 0.0
  },
  "shadow_prices": null
 }
}
